In Unity3D, there are several ways to make a GameObject not receive touch events depending on what type of touch system you're using. Here are the most common scenarios:

## 1. UI Elements (Canvas-based)

### Disable Raycast Target
```csharp
using UnityEngine;
using UnityEngine.UI;

// For UI elements like Button, Image, Text, etc.
GetComponent<Graphic>().raycastTarget = false;
```

### Remove or Disable GraphicRaycaster
```csharp
// On the Canvas
GetComponent<GraphicRaycaster>().enabled = false;
```

## 2. 3D GameObjects with Colliders

### Remove or Disable Collider
```csharp
// Remove collider completely
Destroy(GetComponent<Collider>());

// Or disable it
GetComponent<Collider>().enabled = false;
```

### Change Layer and Physics Settings
```csharp
// Move to a layer that doesn't interact with raycasting
gameObject.layer = LayerMask.NameToLayer("IgnoreRaycast");
```

## 3. Custom Touch/Input Systems

### Disable MonoBehaviour Scripts
```csharp
// Disable specific touch handling scripts
GetComponent<YourTouchScript>().enabled = false;

// Or disable the entire GameObject
gameObject.SetActive(false);
```

### Add Ignore Tag or Component
```csharp
// Method 1: Use tags
gameObject.tag = "NoTouch";

// Then in your touch detection code:
if (hit.collider.CompareTag("NoTouch"))
    return; // Ignore this object

// Method 2: Create a marker component
public class IgnoreTouch : MonoBehaviour { }

// Add it to objects you want to ignore
gameObject.AddComponent<IgnoreTouch>();

// In touch detection:
if (hit.collider.GetComponent<IgnoreTouch>() != null)
    return; // Ignore this object
```

## 4. Raycast-based Touch Detection

### Modify Raycast Layer Mask
```csharp
public class TouchManager : MonoBehaviour
{
    [SerializeField] private LayerMask touchableLayers = -1;

    void Update()
    {
        if (Input.GetMouseButtonDown(0))
        {
            Ray ray = Camera.main.ScreenPointToRay(Input.mousePosition);
            RaycastHit hit;

            // Only raycast against specific layers
            if (Physics.Raycast(ray, out hit, Mathf.Infinity, touchableLayers))
            {
                // Handle touch
            }
        }
    }
}
```

## 5. Event System Override

### Block Events with Higher Priority Object
```csharp
using UnityEngine;
using UnityEngine.EventSystems;

public class TouchBlocker : MonoBehaviour, IPointerDownHandler, IPointerUpHandler
{
    public void OnPointerDown(PointerEventData eventData)
    {
        // Block the event from reaching objects behind this one
        eventData.Use();
    }

    public void OnPointerUp(PointerEventData eventData)
    {
        eventData.Use();
    }
}
```

## 6. Complete Example Script

```csharp
using UnityEngine;
using UnityEngine.UI;

public class TouchEventManager : MonoBehaviour
{
    public enum TouchBlockMethod
    {
        DisableCollider,
        DisableRaycastTarget,
        ChangeLayer,
        DeactivateObject
    }

    public void BlockTouchEvents(GameObject target, TouchBlockMethod method)
    {
        switch (method)
        {
            case TouchBlockMethod.DisableCollider:
                var collider = target.GetComponent<Collider>();
                if (collider) collider.enabled = false;
                break;

            case TouchBlockMethod.DisableRaycastTarget:
                var graphic = target.GetComponent<Graphic>();
                if (graphic) graphic.raycastTarget = false;
                break;

            case TouchBlockMethod.ChangeLayer:
                target.layer = LayerMask.NameToLayer("IgnoreRaycast");
                break;

            case TouchBlockMethod.DeactivateObject:
                target.SetActive(false);
                break;
        }
    }

    public void RestoreTouchEvents(GameObject target, TouchBlockMethod method)
    {
        switch (method)
        {
            case TouchBlockMethod.DisableCollider:
                var collider = target.GetComponent<Collider>();
                if (collider) collider.enabled = true;
                break;

            case TouchBlockMethod.DisableRaycastTarget:
                var graphic = target.GetComponent<Graphic>();
                if (graphic) graphic.raycastTarget = true;
                break;

            case TouchBlockMethod.ChangeLayer:
                target.layer = 0; // Default layer
                break;

            case TouchBlockMethod.DeactivateObject:
                target.SetActive(true);
                break;
        }
    }
}
```

Choose the method that best fits your specific use case. For UI elements, disabling `raycastTarget` is usually the best approach. For 3D objects, disabling the collider or changing the layer works well.

